/**
 * Builder pour la construction du contexte de l'application
 * Responsable de l'instanciation, l'enregistrement et l'initialisation de tous les services
 */
export class AppContextBuilder {
  /** Conteneur de services pour l'injection de dépendances */
  private services = new ServicesContainer();

  /**
   * Construit le contexte complet de l'application
   *
   * Cette méthode suit un processus en 4 étapes :
   * 1. Création de la structure de base du contexte
   * 2. Instanciation de tous les services
   * 3. Enregistrement des services dans le conteneur
   * 4. Initialisation asynchrone de tous les services   *
   * @returns Le contexte de l'application prêt à l'emploi
   */
  public async buildContext(): Promise<IAppContext> {
    // ============================================================================
    // ÉTAPE 1 : Préparation du shell du contexte
    // ============================================================================
    const cli = {
      name: "mclp",
      version: "1.0.0",
      description: "CLI de génération et gestion de projet",
      rootPath: process.cwd(),
      services: this.services,
      config: this.getDefaultConfig(),
    } as unknown as IAppContext;

    // ============================================================================
    // ÉTAPE 2 : Instanciation de tous les services
    // ============================================================================
    // Chaque service reçoit le contexte complet et implémente IBaseService
    // L'ordre d'instanciation n'est pas critique car les dépendances sont résolues
    // via le contexte partagé

    cli.ai = new AiService(cli);
    cli.ast = new AstService(cli);
    cli.case = new CaseService(cli);
    cli.tool = new ToolService(cli);
    cli.state = new StateService(cli);
    cli.plugin = new PluginService(cli);
    cli.db = new DataManagerService(cli);
    cli.logger = new LoggerService(cli);
    cli.generator = new GeneratorService(cli);
    cli.promptService = new PromptService(cli);
    cli.configService = new ConfigService(cli);
    cli.fileSystem = new FileSystemService(cli);
    cli.architecture = new ArchitectureService(cli);
    cli.templateService = new TemplateService(cli);
    cli.errorHandler = new HandlerErrorService(cli);

    // ============================================================================
    // ÉTAPE 3 : Enregistrement automatique dans le conteneur
    // ============================================================================
    this.registerAllServices(cli);

    // ============================================================================
    // ÉTAPE 4 : Initialisation asynchrone de tous les services
    // ============================================================================
    // Utilisation de la méthode du conteneur pour éviter la duplication de code
    await this.services.initializeAll();

    return cli;
  }

  /**
   * Enregistre tous les services du contexte dans le conteneur
   * Permet l'injection de dépendances via le pattern Service Locator   *
   * @param ctx - Le contexte contenant tous les services instanciés
   */
  private registerAllServices(ctx: IAppContext): void {
    /**
     * Mapping entre les noms de services (clés du conteneur) et leurs instances
     * Le nom de service est utilisé pour la récupération via services.get<T>(name)
     */
    const serviceEntries: readonly [string, IBaseService][] = [
      ["AiService", ctx.ai],
      ["AstService", ctx.ast],
      ["LoggerService", ctx.logger],
      ["FileSystemService", ctx.fileSystem],
      ["CaseService", ctx.case],
      ["ToolService", ctx.tool],
      ["StateService", ctx.state],
      ["PluginService", ctx.plugin],
      ["DataManagerService", ctx.db],
      ["GeneratorService", ctx.generator],
      ["PromptService", ctx.promptService],
      ["ConfigService", ctx.configService],
      ["ArchitectureService", ctx.architecture],
      ["TemplateService", ctx.templateService],
      ["HandlerErrorService", ctx.errorHandler],
    ];

    // Enregistrement de chaque service dans le conteneur
    for (const [name, instance] of serviceEntries) {
      this.services.register(name, instance);
    }
  }

  /**
   * Retourne la configuration par défaut de la CLI
   * Ces valeurs peuvent être surchargées par un fichier de configuration   *
   * @returns Configuration par défaut
   */
  private getDefaultConfig(): ICliConfig {
    return {
      /** Chemin local des templates du projet */
      templatesPath: "./templates",
      /** Chemin global des templates partagés (home directory) */
      globalTemplatesPath: "~/.scrofolder",
      /** Niveau de log (debug, info, warn, error) */
      logLevel: "debug",
      /** Thème de la CLI */
      theme: "default",
    };
  }
}

import { Command } from "commander";
import { IAppContext } from "../types/context.interface.js";
import {
  ICommandClass,
  ICommand,
  ICommandOption,
} from "../types/command.interface.js";
import { HandlerErrorService } from "../services/handler-error.service.js";
import { AnyOptions } from "@/types/cli-options.type.js";

/**
 * Classe principale de l'application CLI
 * Gère l'enregistrement des commandes et l'exécution du programme
 */
export class App {
  /** Instance de Commander.js pour gérer la CLI */
  private program = new Command();

  /**
   * Constructeur de l'application
   * @param cli - Contexte de l'application contenant tous les services et configurations
   */
  constructor(private cli: IAppContext) {
    // Configuration globale de l'application
    this.program
      .name("mclp")
      .version(this.cli.version || "1.0.0")
      .description("CLI de génération et gestion de projet");
  }

  /**
   * Configure la gestion globale des erreurs via le HandlerErrorService
   * Cette méthode est appelée au démarrage pour intercepter toutes les erreurs non gérées
   */
  // private setupErrorHandling(): void {
  //   const errorHandler = this.cli.services.get<HandlerErrorService>("HandlerErrorService");
  //   if (errorHandler) {
  //     errorHandler.setupGlobalHandlers();
  //   }
  // }

  /**
   * Enregistre une commande dans l'application CLI
   *
   * @param CommandClass - Classe de commande à instancier et enregistrer
   *
   * @example
   * app.registerCommand(GenerateCommand);
   * // Permet ensuite d'utiliser : mclp generate service User
   */
  public registerCommand(CommandClass: ICommandClass): void {
    // Instanciation de la commande avec le contexte de l'application
    const cmdInstance: ICommand = new CommandClass(this.cli);

    // Récupération de la signature des arguments (ex: "<type> <name>" ou "[args...]")
    // Par défaut, on accepte un nombre illimité d'arguments optionnels
    const signature: string = cmdInstance.arguments ?? "[args...]";

    // Création de la commande dans Commander.js
    const cmd = this.program
      .command(`${cmdInstance.name} ${signature}`.trim())
      .description(cmdInstance.description);

    // Enregistrement des alias de la commande (ex: "g" pour "generate")
    if (cmdInstance.aliases?.length) {
      cmd.aliases(cmdInstance.aliases);
    }

    // Enregistrement des options de la commande (ex: --force, --dry-run)
    if (cmdInstance.options?.length) {
      cmdInstance.options.forEach((opt) => {
        if (opt.type === "boolean") {
          cmd.option(opt.flags, opt.description, opt.defaultValue ?? false);
        } else {
          cmd.option(opt.flags, opt.description);
        }
      });
    }

    cmd.action(async (...actionArgs: unknown[]) => {
      const errorHandler = this.cli.services.get<HandlerErrorService>(
        "HandlerErrorService",
      );

      try {
        // Commander passe généralement l'instance Command en dernier
        const last = actionArgs[actionArgs.length - 1];
        const positional =
          last instanceof Command ? actionArgs.slice(0, -1) : actionArgs;

        const cleanArgs: string[] = positional.flatMap(
          (a: unknown): string[] => {
            if (Array.isArray(a)) return a.map(String);
            if (
              typeof a === "string" ||
              typeof a === "number" ||
              typeof a === "boolean"
            )
              return [String(a)];
            return []; // drop objets (Command, options internes, etc.)
          },
        );

        const raw = cmd.opts();
        const rawOptions = this.toAnyOptions(raw); // type-guard runtime (cf. plus bas)
        const options = this.coerceOptions(rawOptions, cmdInstance.options); // (cf. plus bas)

        // IMPORTANT: utilise run() si disponible (BaseCommand)
        if (typeof cmdInstance.run === "function") {
          await cmdInstance.run(cleanArgs, options as AnyOptions);
        } else {
          await cmdInstance.execute(cleanArgs, options as AnyOptions);
        }
      } catch (error) {
        if (errorHandler) errorHandler.handle(error as Error);
        else {
          console.error("❌ Erreur commande :", error);
          process.exitCode = 1;
        }
      }
    });
  }

  /**
   * Lance l'application CLI et parse les arguments de la ligne de commande
   * Point d'entrée principal après l'enregistrement de toutes les commandes
   */
  public async run(): Promise<void> {
    const errorHandler = this.cli.services.get<HandlerErrorService>(
      "HandlerErrorService",
    );
    try {
      // Parse les arguments du processus (process.argv)
      await this.program.parseAsync(process.argv);
    } catch (error) {
      // En cas d'erreur fatale, on utilise le gestionnaire d'erreurs

      if (errorHandler) {
        errorHandler.handle(
          error as Error,
          "❌ Échec du démarrage de l'application :",
        );
      } else {
        // Fallback si le gestionnaire d'erreurs n'est pas disponible
        console.error("❌ Échec du démarrage de l'application :", error);
        process.exit(1);
      }
    }
  }

  private isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value);
  }
  private toAnyOptions(value: unknown): AnyOptions {
    return this.isRecord(value) ? value : {};
  }
  public coerceOptions(
    raw: Record<string, unknown>,
    spec?: ICommandOption[],
  ): Record<string, unknown> {
    if (!spec?.length) return raw;

    const out: Record<string, unknown> = { ...raw };

    for (const opt of spec) {
      const long = opt.flags
        .split(/[ ,|]+/)
        .find((f) => f.startsWith("--"))
        ?.replace(/^--/, "")
        ?.replace(/^no-/, "");

      if (!long) continue;

      // Defaults (si non fourni)
      if (
        out[long] === undefined &&
        "defaultValue" in opt &&
        opt.defaultValue !== undefined
      ) {
        out[long] = opt.defaultValue;
      }

      // Cast number
      if (opt.type === "number") {
        const v = out[long];
        if (typeof v === "string") {
          const n = Number(v);
          if (!Number.isNaN(n)) out[long] = n;
        }
      }
    }

    return out;
  }
}

export enum ErrorCode {
  INTERNAL_ERROR = "INTERNAL_ERROR",
  VALIDATION_ERROR = "VALIDATION_ERROR",
  FILESYSTEM_ERROR = "FILESYSTEM_ERROR",
  TEMPLATE_NOT_FOUND = "TEMPLATE_NOT_FOUND",
  SERVICE_NOT_FOUND = "SERVICE_NOT_FOUND",
}

export class CliError extends Error {
  constructor(
    public readonly message: string,
    public readonly code: ErrorCode = ErrorCode.INTERNAL_ERROR,
    public readonly exitCode: number = 1,
  ) {
    super(message);
    this.name = "CliError";
  }
}

export class ValidationError extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.VALIDATION_ERROR, 1);
  }
}

export class FilesystemError extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.FILESYSTEM_ERROR, 1);
  }
}

export class TemplateNotFoundError extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.TEMPLATE_NOT_FOUND, 1);
  }
}

export class ServiceNotFoundError extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.SERVICE_NOT_FOUND, 1);
  }
}

export class InternalError extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.INTERNAL_ERROR, 1);
  }
}

export class UnknownError extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.INTERNAL_ERROR, 1);
  }
}

export class NotImplemented extends CliError {
  constructor(message: string) {
    super(message, ErrorCode.INTERNAL_ERROR, 1);
  }
}

import { App } from "./core/App.js";
import { MakeCommand } from "./commands/make.command.js";
import { TreeCommand } from "./commands/tree.command.js";
import { AppContextBuilder } from "./context/context.js";
import { GenerateCommand } from "./commands/GenerateCommand.js";
import { HandlerErrorService } from "./services/handler-error.service.js";

/**
 * Point d'entrée principal de la CLI
 *
 * Cette fonction bootstrap orchestre le démarrage complet de l'application :
 * 1. Construction du contexte avec tous les services
 * 2. Initialisation de l'application
 * 3. Enregistrement des commandes disponibles
 * 4. Lancement de l'application
 */
async function bootstrap(): Promise<void> {
  try {
    // ============================================================================
    // ÉTAPE 1 : Construction du contexte de l'application
    // ============================================================================
    // Le contexte contient tous les services (Logger, FileSystem, Generator, etc.)
    // ainsi que la configuration de l'application
    const builder = new AppContextBuilder();
    const cli = await builder.buildContext();
    cli.services
      .get<HandlerErrorService>("HandlerErrorService")
      .setupGlobalHandlers();

    // 1) init services
    await cli.services.initializeAll();

    // 2) setup handlers après init
    cli.services
      .get<HandlerErrorService>("HandlerErrorService")
      .setupGlobalHandlers();

    // ============================================================================
    // ÉTAPE 2 : Initialisation de l'application
    // ============================================================================
    // L'application reçoit le contexte complet et configure Commander.js
    const app = new App(cli);

    // ============================================================================
    // ÉTAPE 3 : Enregistrement des commandes disponibles
    // ============================================================================
    /**
     * Chaque commande est enregistrée auprès de l'application
     * Les commandes seront automatiquement disponibles via la CLI
     *
     * Exemples d'utilisation :
     * - mclp make service User
     * - mclp generate component Button
     * - mclp tree
     * - mclp init
     * - mclp ia "génère un service utilisateur"
     */
    app.registerCommand(MakeCommand);
    app.registerCommand(TreeCommand);
    app.registerCommand(GenerateCommand);
    // app.registerCommand(InitCommand);
    // app.registerCommand(IaCommand);

    // TODO: Automatiser l'enregistrement en scannant le dossier commands
    // Cela permettrait d'ajouter de nouvelles commandes sans modifier ce fichier

    // ============================================================================
    // ÉTAPE 4 : Lancement de l'application
    // ============================================================================
    // Parse les arguments de la ligne de commande et exécute la commande appropriée
    await app.run();
  } catch (error) {
    /**
     * Gestion d'erreur de dernier recours
     * Cette gestion s'active uniquement si le HandlerErrorService n'est pas encore prêt
     * ou si une erreur se produit avant son initialisation
     */
    console.error("❌ Erreur fatale lors du démarrage de la CLI :");
    console.error(error);
    process.exit(1);
  }
}

// ============================================================================
// Lancement du bootstrap
// ============================================================================
// Note : Utilisation de top-level await (nécessite Node.js >= 14.8 avec ESM)
await bootstrap();

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";
import { AiService } from "./services/ai.service.js";
import path from "node:path";
import { pathToFileURL } from "node:url";

const aiService = new AiService();
/*
Capacité	Utilité pour ton projet
resources:	Permet à l'IA de consulter des fichiers en lecture seule (comme tes schémas de base de données) sans passer par un outil.
prompts:	Permet de proposer à l'IA des modèles de messages (ex: un prompt "Code Review" pré-configuré).
logging:	Permet au serveur d'envoyer des flux de logs en temps réel au client
*/
const server = new Server(
  { name: "mclp-mcp-server", version: "1.0.0" },
  {
    capabilities: {
      // Indique que ton serveur propose des outils exécutables
      tools: {},

      // Optionnel : si tu veux que l'IA puisse lire des ressources (fichiers de log, config, etc.)
      // resources: {},

      // Optionnel : si tu veux proposer des "prompts" pré-enregistrés
      // prompts: {}
    },
  },
);

/**
 * 1. DÉCOUVERTE : Expose tes plugins à l'application cliente (ex: Claude)
 */
server.setRequestHandler(ListToolsRequestSchema, async () => {
  const tools = await aiService.listTools();
  const definitions = [];

  for (const name of tools) {
    try {
      // ON VISE LE DOSSIER SOURCE (OU DIST SELON TA CONFIG)
      // Utilise process.cwd() pour être sûr de partir de la racine du projet
      const pluginPath = path.resolve(
        process.cwd(),
        "src",
        "plugins",
        `${name}.plugin.js`,
      );

      const fileUrl = pathToFileURL(pluginPath).href;
      const module = await import(`${fileUrl}?update=${Date.now()}`);

      if (module.default?.definition) {
        definitions.push(module.default.definition);
      }
    } catch (error: any) {
      // Log l'erreur dans stderr pour ne pas polluer le flux JSON-RPC (stdio)
      console.error(`[MCP] Erreur sur ${name}:`, error.message);
    }
  }

  return { tools: definitions };
});

/**
 * 2. EXÉCUTION : Reçoit l'ordre de l'application cliente et lance le plugin
 */
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  try {
    const result = await aiService.executeTool(name, args ? [args] : []);
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
    };
  } catch (error: any) {
    return {
      isError: true,
      content: [{ type: "text", text: error.message }],
    };
  }
});

/**
 * 3. DÉMARRAGE : Utilise STDIO (Standard Input/Output) pour communiquer
 */
const transport = new StdioServerTransport();
await server.connect(transport);
console.error("🚀 MCP Server running on stdio");

/**
 * Plugin: Architect
 * Rôle: Analyse la structure du projet pour donner du contexte à l'IA.
 */
export default class ArchitectPlugin {
  // Définition statique pour que l'Hôte MCP puisse décrire l'outil à l'IA
  static definition = {
    name: "architect",
    description:
      "Analyse la structure des fichiers source et les interfaces du projet.",
    inputSchema: {
      type: "object",
      properties: {
        deepScan: { type: "boolean", description: "Scanner les sous-dossiers" },
      },
    },
  };
  // Définition MCP

  async execute(args, context) {
    context.log("args: ", args);
    context.log("context: ", context);
    context.log("Début de l'analyse structurelle du projet...");

    const projectRoot = "./src";
    const structure = {};

    try {
      // 1. Scanner les dossiers clés
      const folders = ["commands", "services", "interfaces"];

      for (const folder of folders) {
        const folderPath = `${projectRoot}/${folder}`;
        try {
          const files = await context.fs.readdir(folderPath);
          structure[folder] = files;
        } catch (e) {
          structure[folder] = "Dossier non trouvé";
        }
      }

      // 2. Lire l'interface principale pour connaître les capacités
      const interfacePath = "./src/types/ai-service.interface.ts";
      const interfaceContent = await context.fs.readFile(
        interfacePath,
        "utf-8",
      );

      // 3. Synthèse pour l'IA
      const report = {
        date: new Date().toISOString(),
        files: structure,
        capabilities: interfaceContent,
      };

      context.log("Analyse terminée. Voici ma structure actuelle :");
      console.table(structure);

      // On peut même demander à l'IA de commenter cette structure
      const feedback = await context.ai.chat(
        `Voici ma structure actuelle : ${JSON.stringify(structure)}. 
         Mes capacités sont : ${interfaceContent}. 
         Suggère une amélioration ou un nouvel outil manquant.`,
      );

      console.log("\n🤖 Suggestion de l'IA Architecte :");
      console.log(feedback);
    } catch (error) {
      context.log(`Erreur lors de l'analyse : ${error.message}`);
    }
  }
}

