import path from "path";
import fs from "fs-extra";
import { fileURLToPath } from "url";
import { BaseService } from "./base-service.service.js";
import { IFileSystemService } from "@/types/services/file-system.interface.js";
import { IFileNode } from "@/types/commun/file-node.interface.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export class FileSystemService extends BaseService implements IFileSystemService {
  readonly serviceName = "FileSystemService";

  private readonly TS_EXTENSION = ".ts";
  private readonly CLASS_TEMPLATE = "class.ts.txt";
  private readonly DEFAULT_AUTHOR = "MCLP System";

  public excludedDirs = ["node_modules", ".git", "dist", ".vscode"];

  // public init(): Promise<void> {
  //   // Si tu n'as rien à initialiser pour l'instant :
  //   return Promise.resolve();
  // }

  /**
   * Adds additional directories to the exclusion list
   * @param excludedDirs - Array of directory names to exclude
   */
  public setExcludedDirs(excludedDirs: string[]): void {
    this.excludedDirs = [...this.excludedDirs, ...excludedDirs];
  }

  /**
   * Checks if a file or directory exists
   * @param targetPath - Path to check
   * @returns true if exists, false otherwise
   */
  public exists(targetPath: string): boolean {
    this.validatePath(targetPath, "targetPath");
    return fs.existsSync(targetPath);
  }

  /**
   * Creates a directory, including parent directories if needed
   * @param dirPath - Path of directory to create
   */
  public async createDirectory(dirPath: string): Promise<void> {
    this.validatePath(dirPath, "dirPath");
    try {
      await fs.ensureDir(dirPath);
      this.cli.logger.debug(`Directory created or verified: ${dirPath}`);
    } catch (error) {
      const message = `Unable to create directory: ${dirPath}`;
      this.cli.errorHandler.handle(error, message);
      throw error instanceof Error ? error : new Error(message);
    }
  }

  /**
   * Writes content to a file
   * @param filePath - Path of file to write
   * @param content - Content to write
   */
  public async writeFile(filePath: string, content: string): Promise<void> {
    this.validatePath(filePath, "filePath");
    try {
      await fs.outputFile(filePath, content);
      this.cli.logger.debug(`File written: ${filePath}`);
    } catch (error) {
      const message = `writeFile(): Failed to write file: ${filePath}`;
      // this.cli.errorHandler.handle(error, message);
      // throw error instanceof Error ? error : new Error(message);
    }
  }

  /**
   * Writes content to a file in a specific output directory
   * @param basePath - Base directory path
   * @param subDir - Subdirectory within base path
   * @param fileName - Name of the file
   * @param content - Content to write
   */
  public async writeToOutput(
    basePath: string,
    subDir: string,
    fileName: string,
    content: string,
  ): Promise<void> {
    const targetDir = path.join(basePath, subDir);

    if (!this.exists(targetDir)) {
      await this.createDirectory(targetDir);
    }

    const finalPath = path.join(targetDir, fileName);
    await this.writeFile(finalPath, content);
  }

  /**
   * Reads content from a file
   * @param filePath - Path of file to read
   * @returns File content as string
   */
  public async readFile(filePath: string): Promise<string> {
    this.validatePath(filePath, "filePath");
    try {
      return await fs.readFile(filePath, "utf-8");
    } catch (error) {
      const message = `Unable to read file: ${filePath}`;
      this.cli.errorHandler.handle(error, message);
      throw error instanceof Error ? error : new Error(message);
    }
  }

  /**
   * Copies a file from source to destination
   * @param source - Source file path
   * @param destination - Destination file path
   */
  public async copy(source: string, destination: string): Promise<void> {
    this.validatePath(source, "source");
    this.validatePath(destination, "destination");
    try {
      await fs.copy(source, destination);
      this.cli.logger.debug(`Copied from ${source} to ${destination}`);
    } catch (error) {
      const message = `Copy failed: ${source} -> ${destination}`;
      this.cli.errorHandler.handle(error, message);
      throw error instanceof Error ? error : new Error(message);
    }
  }

  /**
   * Resolves path segments into an absolute path
   * @param segments - Path segments to resolve
   * @returns Resolved absolute path
   */
  public resolvePath(...segments: string[]): string {
    return path.resolve(...segments);
  }

  /**
   * Creates a file with optional content
   * @param filePath - Path of file to create
   * @param content - Optional content to write
   */
  public async createFile(filePath: string, content = ""): Promise<void> {
    this.validatePath(filePath, "filePath");
    const dir = path.dirname(filePath);
    if (!this.exists(dir)) {
      await this.createDirectory(dir);
    }
    await this.writeFile(filePath, content);
  }

  public async getDirectoryTree(
    dirPath: string,
    level = 0,
    maxLevel = 0, // 0 = infini
    withMetadata = true,
    config: { excludedDirs: string[]; analyzeExtensions: string[] },
  ): Promise<IFileNode | null> {
    this.validatePath(dirPath, "dirPath");

    const name = path.basename(dirPath);

    // 1. Vérification des exclusions via le tableau du JSON
    if (config.excludedDirs.includes(name)) {
      return null;
    }

    const stats = await fs.stat(dirPath);
    const isDirectory = stats.isDirectory();
    const extension = isDirectory ? "" : path.extname(name).toLowerCase();

    const info: IFileNode = {
      path: dirPath,
      name: name,
      level: level,
      type: isDirectory ? "directory" : "file",
      size: isDirectory ? 0 : stats.size,
      content: "",
      extension: extension,
      metadata: [],
      children: [],
    };

    const reachLimit = maxLevel > 0 && level >= maxLevel;

    if (isDirectory && !reachLimit) {
      const childrenNames = await fs.readdir(dirPath);

      const childrenResults = await Promise.all(
        childrenNames.map((child) =>
          this.getDirectoryTree(
            path.join(dirPath, child),
            level + 1,
            maxLevel,
            withMetadata,
            config,
          ),
        ),
      );

      info.children = childrenResults.filter((child): child is IFileNode => child !== null);
      info.size = info.children.reduce((acc, child) => acc + (child.size || 0), 0);
    } else if (!isDirectory) {
      // 2. Analyse Metadata si l'extension est dans la liste du JSON
      if (withMetadata && config.analyzeExtensions.includes(extension)) {
        try {
          const sourceCode = await fs.readFile(dirPath, "utf-8");
          info.content = sourceCode;
          info.metadata = this.cli.ast.analyzeFileMetadata(dirPath, sourceCode);
        } catch (err) {
          console.warn(`Erreur lecture metadata: ${name}`);
        }
      }
    }

    return this.filterTree(info);
  }
  /**
   * Filters out excluded directories from the tree
   * @param node - File node to filter
   * @returns Filtered file node
   */
  private filterTree(node: IFileNode): IFileNode {
    if (!node.children) return node;

    return {
      ...node,
      children: node.children
        .filter((child: IFileNode) => !this.excludedDirs.includes(child.name))
        .map((child: IFileNode) => this.filterTree(child)),
    };
  }

  /**
   * Creates a directory tree from a JSON file
   * @param sourcePath - Path to JSON file containing tree structure
   * @param targetBaseDir - Base directory where tree will be created
   */
  public async createDirectoryTreeFromJson(
    sourcePath: string,
    targetBaseDir: string,
  ): Promise<void> {
    try {
      const treeData = await this.readJsonFile(sourcePath);
      await this.buildPhysicalTree(treeData, targetBaseDir);
      this.cli.logger.success("Directory tree recreated successfully!");
    } catch (error) {
      const message = `Error reading/parsing JSON: ${sourcePath}`;
      this.cli.errorHandler.handle(error, message);
      throw error instanceof Error ? error : new Error(message);
    }
  }

  /**
   * Reads and parses a JSON file into a FileNode
   * @param filePath - Path to JSON file
   * @returns Parsed file node
   */
  private async readJsonFile(filePath: string): Promise<IFileNode> {
    try {
      const raw: unknown = await fs.readJson(filePath);

      if (!this.isFileNode(raw)) {
        throw new Error("Invalid JSON structure: IFileNode expected");
      }

      return raw;
    } catch (error) {
      const message = `Error reading/parsing JSON: ${filePath}`;
      this.cli.errorHandler.handle(error, message);
      throw error instanceof Error ? error : new Error(message);
    }
  }

  /**
   * Type guard to check if value is a valid IFileNode
   * @param value - Value to check
   * @returns true if value is IFileNode
   */
  private isFileNode(value: unknown): value is IFileNode {
    if (!value || typeof value !== "object") return false;

    const node = value as IFileNode;
    return (
      typeof node.name === "string" &&
      typeof node.path === "string" &&
      typeof node.type === "string" &&
      (node.type === "file" || node.type === "directory") &&
      typeof node.level === "number" &&
      typeof node.size === "number" &&
      typeof node.content === "string" &&
      typeof node.extension === "string" &&
      Array.isArray(node.metadata) &&
      Array.isArray(node.children)
    );
  }

  /**
   * Builds the physical directory tree from a FileNode structure
   * @param node - File node to create
   * @param currentPath - Current directory path
   */
  private async buildPhysicalTree(node: IFileNode, currentPath: string): Promise<void> {
    const fullPath = path.join(currentPath, node.name);

    if (node.type === "directory" || node.children) {
      await this.createDirectory(fullPath);
      this.cli.logger.info(`[DIR] ${fullPath}`);

      if (node.children && Array.isArray(node.children)) {
        for (const child of node.children) {
          await this.buildPhysicalTree(child, fullPath);
        }
      }
    } else {
      const content = await this.getContentForFile(node, fullPath);
      await this.writeFile(fullPath, content);
      this.cli.logger.info(`[FILE] ${fullPath}`);
    }
  }

  /**
   * Gets content for a file, applying templates if necessary
   * @param node - File node
   * @param fullPath - Full path to the file
   * @returns File content
   */
  private async getContentForFile(node: IFileNode, fullPath: string): Promise<string> {
    if (node.content) {
      return node.content;
    }

    if (fullPath.endsWith(this.TS_EXTENSION)) {
      return await this.applyTemplate(node.name);
    }

    return "";
  }

  /**
   * Applies a template to generate file content
   * @param fileName - Name of the file
   * @returns Generated content from template
   */
  private async applyTemplate(fileName: string): Promise<string> {
    try {
      const templatePath = path.resolve(__dirname, "..", "templates", this.CLASS_TEMPLATE);

      this.cli.logger.debug(`Attempting to load template: ${templatePath}`);

      if (!this.exists(templatePath)) {
        this.cli.logger.warn(`Template not found: ${templatePath}`);
        return "";
      }

      const rawTemplate = await this.readFile(templatePath);
      this.cli.logger.debug(`Template loaded for ${fileName}, length: ${rawTemplate.length}`);

      const content = this.cli.templateService.compile(rawTemplate, {
        name: fileName.replace(this.TS_EXTENSION, ""),
        author: this.DEFAULT_AUTHOR,
      });

      this.cli.logger.debug(`Content generated for ${fileName}, length: ${content.length}`);
      return content;
    } catch (error) {
      this.cli.logger.warn(`Template not found for ${fileName}, creating empty file.`);
      return "";
    }
  }

  /**
   * Validates that a path is not empty
   * @param filePath - Path to validate
   * @param paramName - Name of parameter for error message
   */
  private validatePath(filePath: string, paramName: string): void {
    if (!filePath || filePath.trim() === "") {
      throw new Error(`${paramName} cannot be empty`);
    }
  }
}

import path from "path";
import { BaseService } from "./base-service.service.js";
import { IGeneratorService } from "@/types/services/generator.interface.js";
import { IGenerateOptions } from "@/commands/GenerateCommand.js";

export class GeneratorService extends BaseService implements IGeneratorService {
  readonly serviceName = "GeneratorService";

  private content = "";
  private fileName = "";
  private folder = "";
  private targetPath = "";

  public async newComponent(type: string, name: string, options: IGenerateOptions): Promise<void> {
    this.fileName = this.getFileName(type, name);
    this.folder = this.getTargetFolder(type);
    this.targetPath = path.join(this.cli.rootPath, this.folder, this.fileName);

    switch (type) {
      case "service":
        this.content = this.getTemplateContentService(name);
        await this.save(this.targetPath, this.content, options);
        this.fileName = this.getFileName("interface", name);
        this.targetPath = `${this.getTargetFolder("interface")}/${this.fileName}`;
        this.content = this.getTemplateContentInterfaceService(name);
        await this.save(this.targetPath, this.content, options);
        break;
      case "command":
        this.content = this.getTemplateContentCommand(name);
        await this.save(this.targetPath, this.content, options);
        break;
      case "template":
        this.content = this.getTemplateContentTemplate(name);
        await this.save(this.targetPath, this.content, options);
        break;
    }

    if (options.dryRun) {
      this.cli.logger.info(`[DRY-RUN] Créerait le fichier : ${this.targetPath}`);
      return;
    }
  }

  private getFileName(type: string, name: string): string {
    switch (type) {
      case "service":
        return `${this.cli.case.toKebabCase(name)}.service.ts`;
      case "interface":
        return `${this.cli.case.toKebabCase(name)}-service.interface.ts`;
      case "command":
        return `${this.cli.case.toKebabCase(name)}.command.ts`;
      case "template":
        return `${this.cli.case.toKebabCase(name)}.template.ts`;
      default:
        return `${this.cli.case.toKebabCase(name)}.ts`;
    }
  }

  private getTargetFolder(type: string): string {
    switch (type) {
      case "service":
        return "src/services";
      case "interface":
        return "src/types/services";
      case "command":
        return "src/commands";
      case "template":
        return "src/templates";
      default:
        return "src";
    }
  }

  private getTemplateContentCommand(name: string): string {
    const className = this.cli.case.toPascalCase(name);
    const commandName = this.cli.case.toKebabCase(name);
    return `import { BaseCommand } from "./BaseCommand.js";
      import { ValidationError } from "@/errors/cli-errors.js";

      export class ${className}Command extends BaseCommand {
        public name = "${commandName}";
        public description = "Génère un nouvel élément de la CLI (Service, Command, Template)";
        public arguments = "<type> [names...]";
        public aliases = ["m"];

        public options = [
          { flags: "-f, --force", description: "Écraser les fichiers existants", defaultValue: false },
          { flags: "-d, --dry-run", description: "Simuler la création sans écrire", defaultValue: false },
        ];

        public async execute(args: string[], options: any): Promise<void> {
          const [type, ...names] = args; 
          this.logger.success("✅ ${name} Création de ${name} : Opération terminée.");
        }
      }
      `;
  }

  private getTemplateContentTemplate(name: string): string {
    return `import { BaseService } from "./base-service.service.js";\n\nexport class ${name}Service extends BaseService {}`;
  }

  private getTemplateContentService(name: string): string {
    const newName = this.cli.case.toKebabCase(name);
    const className = this.cli.case.toPascalCase(newName);
    const serviceName = `${this.cli.case.toKebabCase(newName)}-service`;
    return `import { BaseService } from "./base-service.service.js";      
import { I${className}Service } from "@/types/services/${serviceName}.interface.js";

export class ${className}Service extends BaseService implements I${className}Service {
  readonly serviceName = "${className}Service";

  public async init(): Promise<void> {
    // Implémentation par défaut vide
    // return Promise.resolve();
  }
  }
      `;
  }

  private getTemplateContentInterfaceService(name: string): string {
    const className = this.cli.case.toPascalCase(name);
    return `export interface I${className}Service {
serviceName: string;
init(): Promise<void>
}`;
  }

  private async save(
    targetPath: string,
    content: string,
    options: IGenerateOptions,
  ): Promise<void> {
    const exists = this.cli.fileSystem.exists(targetPath);
    if (exists && !options.force) {
      this.cli.logger.warn(`Le fichier ${targetPath} existe déjà. Saute.`);
      return;
    }
    await this.cli.fileSystem.writeFile(targetPath, content);
  }
}

import { IHandlerErrorService } from "@/types/services/error-handler.interface.js";
import { BaseService } from "./base-service.service.js";
import { CliError } from "@/errors/cli-errors.js";
import { IAppContext } from "@/types/context.interface.js";

export class HandlerErrorService extends BaseService implements IHandlerErrorService {
  readonly serviceName = "HandlerErrorService";

  constructor(cli: IAppContext) {
    super(cli);
  }

  /**
   * Configure les écouteurs globaux pour Node.js.
   * Empêche la CLI de crash sans loguer l'erreur.
   */
  public setupGlobalHandlers(): void {
    process.on("uncaughtException", (error: Error) => {
      this.handle(error, "Uncaught Exception");
    });

    process.on("unhandledRejection", (reason: unknown) => {
      this.handle(
        reason instanceof Error ? reason : new Error(String(reason)),
        "Unhandled Rejection",
      );
    });
  }

  /**
   * Méthode centrale pour traiter toute erreur de l'application.
   * Cette méthode est ultra-sécurisée et ne devrait jamais planter.
   * @param error erreur à traiter
   * @param contextMessage message contextuel optionnel
   */
  public handle(error: unknown, contextMessage?: string): void {
    try {
      // 1️⃣ Normaliser unknown → Error
      const err: Error =
        error instanceof Error
          ? error
          : new Error(typeof error === "string" ? error : JSON.stringify(error));

      const isCliError = err instanceof CliError;
      const message = isCliError ? err.message : `An unexpected error occurred: ${err.message}`;
      const exitCode = isCliError ? (err as CliError).exitCode : 1;

      // 2️⃣ Logger SAFE avec protection totale
      this.safeLogError(contextMessage, message);

      // 3️⃣ Stack trace en debug uniquement (ultra safe)
      this.safeLogStackTrace(err);

      // 4️⃣ Sortie propre
      process.exit(exitCode);
    } catch (handlerError) {
      // Si même le handler d'erreur plante, on utilise console brut
      console.error("❌ Critical error in error handler:");
      console.error("Context:", contextMessage ?? "Unknown");
      console.error("Original error:", error);
      console.error("Handler error:", handlerError);
      process.exit(1);
    }
  }

  /**
   * Log une erreur de manière sécurisée avec plusieurs fallbacks.
   * Cette méthode ne devrait jamais planter.
   * @param contextMessage contexte de l'erreur
   * @param message message d'erreur
   */
  private safeLogError(contextMessage: string | undefined, message: string): void {
    try {
      const logger = this.cli?.logger;

      // Tentative d'utilisation du logger configuré
      if (logger && typeof logger.error === "function") {
        const finalMessage = contextMessage ? `${contextMessage}: ${message}` : message;
        logger.error(finalMessage);
        return;
      }
    } catch (loggerError) {
      // Le logger a planté, on affiche un warning et on continue vers le fallback
      console.error("⚠️  Logger failed, falling back to console:", loggerError);
    }

    // Fallback : utilisation de console.error
    const finalMessage = contextMessage ? `${contextMessage}: ${message}` : message;
    console.error("❌", finalMessage);
  }

  /**
   * Affiche la stack trace seulement en mode debug.
   * Cette méthode ne plante jamais, même si la récupération du log level échoue.
   * @param err erreur dont on veut afficher la stack
   */
  private safeLogStackTrace(err: Error): void {
    try {
      const logLevel = this.getLogLevel();

      if (logLevel === "debug" && err.stack) {
        console.error("\n📍 Stack trace:");
        console.error(err.stack);
      }
    } catch (stackError) {
      // Si la récupération du log level plante, on affiche quand même la stack
      // en cas d'erreur critique (mieux vaut trop d'info que pas assez)
      if (err.stack) {
        console.error("\n⚠️  Stack trace (log level check failed):");
        console.error(err.stack);
      }
    }
  }

  /**
   * Récupère le log level de manière ultra-sécurisée avec plusieurs fallbacks.
   * Cette méthode ne plante jamais.
   * @returns le log level ou undefined si impossible à déterminer
   */
  private getLogLevel(): string | undefined {
    try {
      // Méthode 1 : Via this.cli.config.logLevel (standard)
      if (this.cli?.config?.logLevel) {
        return this.cli.config.logLevel;
      }

      // Méthode 2 : Via une variable d'environnement
      const envLogLevel = process.env.LOG_LEVEL;
      if (envLogLevel) {
        return envLogLevel;
      }

      // Méthode 3 : Via les arguments de ligne de commande
      if (process.argv.includes("--debug") || process.argv.includes("-d")) {
        return "debug";
      }

      if (process.argv.includes("--verbose") || process.argv.includes("-v")) {
        return "verbose";
      }

      // Valeur par défaut
      return undefined;
    } catch {
      // En cas d'erreur dans la récupération, on retourne undefined
      return undefined;
    }
  }

  /**
   * Méthode utilitaire pour forcer l'affichage de détails en mode debug.
   * Utile pour le développement.
   * @param title titre de la section de debug
   * @param data données à afficher
   */
  public debugLog(title: string, data: unknown): void {
    try {
      const logLevel = this.getLogLevel();

      if (logLevel === "debug") {
        console.log(`\n🔍 ${title}:`);
        console.log(JSON.stringify(data, null, 2));
      }
    } catch {
      // En cas d'erreur, on ignore silencieusement
    }
  }

  /**
   * Vérifie si le service est correctement initialisé.
   * Utile pour le debugging.
   * @returns true si le service est correctement configuré
   */
  public isProperlyConfigured(): boolean {
    try {
      return !!(this.cli?.logger && typeof this.cli.logger.error === "function");
    } catch {
      return false;
    }
  }

  /**
   * Retourne un diagnostic de l'état du service.
   * Utile pour comprendre pourquoi les erreurs ne sont pas loguées correctement.
   * @returns objet contenant les informations de diagnostic
   */
  public getDiagnostics(): {
    hasCliContext: boolean;
    hasLogger: boolean;
    hasConfig: boolean;
    logLevel: string | undefined;
    isFullyConfigured: boolean;
  } {
    try {
      return {
        hasCliContext: !!this.cli,
        hasLogger: !!this.cli?.logger,
        hasConfig: !!this.cli?.config,
        logLevel: this.getLogLevel(),
        isFullyConfigured: this.isProperlyConfigured(),
      };
    } catch {
      return {
        hasCliContext: false,
        hasLogger: false,
        hasConfig: false,
        logLevel: undefined,
        isFullyConfigured: false,
      };
    }
  }
}
