import chalk from "chalk";
import { BaseService } from "./base-service.service.js";
import { ILoggerService } from "@/types/services/logger-service.interface.js";

export class LoggerService extends BaseService implements ILoggerService {
  readonly serviceName = "LoggerService";
  init(): Promise<void> {
    return Promise.resolve();
  }
  info(message: string, meta?: object): void {
    console.log(
      chalk.blue("ℹ"),
      message,
      meta ? chalk.gray(JSON.stringify(meta)) : "",
    );
  }

  success(message: string): void {
    console.log(chalk.green("✔"), chalk.bold(message));
  }

  warn(message: string, meta?: object): void {
    console.warn(chalk.yellow("⚠"), chalk.yellow(message), meta || "");
  }

  error(message: string, error?: Error): void {
    console.error(chalk.red("✖"), chalk.red.bold(message));
    if (error && this.config.logLevel === "debug") {
      console.error(chalk.gray(error.stack));
    }
  }

  debug(message: string, meta?: object): void {
    if (this.config.logLevel === "debug") {
      console.log(chalk.magenta("⚙ [DEBUG]"), message, meta || "");
    }
  }
}

import { BaseService } from "./base-service.service.js";
import { IPluginService } from "@/types/plugin-service.interface.js";
// import { DataManagerService } from "./data-manager.service.js";

export class PluginService extends BaseService implements IPluginService {
  readonly serviceName = "PluginService";

  public override async init(): Promise<void> {
    // Si tu n'as rien à initialiser pour l'instant :
    return Promise.resolve();
  }
  plugins = new Map<string, any>();

  // Charge dynamiquement tous les plugins d'un dossier
  async registerPlugin(PluginClass: any) {
    const definition = PluginClass.definition;
    this.plugins.set(definition.name, new PluginClass());
    console.log(`[PluginService] Plugin chargé : ${definition.name}`);
  }

  // Point d'entrée unique pour exécuter n'importe quel plugin
  async run(pluginName: string, args: string[]): Promise<any> {
    const plugin = this.plugins.get(pluginName);
    if (!plugin) throw new Error(`Plugin ${pluginName} introuvable.`);

    // Voici l'injection : on prépare le contexte ici
    const context = {
      db: this.cli.db,
      log: (msg: string) => console.log(`[${pluginName}] ${msg}`),
      timestamp: new Date().toISOString(),
    };

    try {
      // On exécute le plugin avec les arguments et le contexte injecté
      return await plugin.execute(args, context);
    } catch (error: any) {
      console.error(`Erreur d'exécution dans ${pluginName}:`, error);
      return { success: false, error: error.message };
    }
  }

  log(msg: string): void {
    console.log(msg);
  }
}

import inquirer from "inquirer";
import { BaseService } from "./base-service.service.js";
import { IPromptService } from "@/types/services/prompt-service.interface.js";

export class PromptService extends BaseService implements IPromptService {
  readonly serviceName = "PromptService";

  /**
   * Pose une question simple (texte)
   */
  async askText(message: string, name: string = "value"): Promise<string> {
    const result = await inquirer.prompt([
      {
        type: "input",
        name: name,
        message: message,
      },
    ]);
    return result[name];
  }

  /**
   * Propose un choix dans une liste
   */
  async askChoiceList<T>(message: string, choices: string[]): Promise<T> {
    const name = "selection";
    const result = await inquirer.prompt([
      {
        type: "list",
        name: name,
        message: message,
        choices: choices,
      },
    ]);
    return result[name];
  }
  /**
   * Propose un choix dans une liste
   */
  async askChoiceCheckbox<T>(message: string, choices: string[]): Promise<T> {
    const name = "selection";
    const result = await inquirer.prompt([
      {
        type: "checkbox",
        name: name,
        message: message,
        choices: choices,
      },
    ]);
    return result[name];
  }

  /**
   * Demande une confirmation (Oui/Non)
   */
  async confirm(message: string): Promise<boolean> {
    const name = "isConfirmed";
    const result = await inquirer.prompt([
      {
        type: "confirm",
        name: name,
        message: message,
        default: false,
      },
    ]);
    return result[name];
  }
}

import { IServicesContainer } from "@/types/services-container.interface.js";
import { IBaseService } from "@/types/base-service.interface.js";

/**
 * Conteneur de services (Service Container)
 * Implémente le pattern Service Locator pour l'injection de dépendances
 *
 * Ce conteneur permet de :
 * - Enregistrer des services par leur nom
 * - Récupérer des services de manière typée
 * - Initialiser tous les services en une seule fois
 * - Centraliser la gestion du cycle de vie des services
 */
export class ServicesContainer implements IServicesContainer {
  /**
   * Map interne pour stocker les services
   * Clé : nom du service (ex: "LoggerService", "FileSystemService")
   * Valeur : instance du service implémentant IBaseService
   */
  private services = new Map<string, IBaseService>();

  /**
   * Enregistre un service dans le conteneur
   *
   * @param name - Nom unique du service (utilisé pour la récupération)
   * @param service - Instance du service à enregistrer
   *
   * @example
   * container.register("LoggerService", new LoggerService(context));
   */
  public register(name: string, service: IBaseService): void {
    this.services.set(name, service);
  }

  /**
   * Récupère un service par son nom avec typage fort
   *
   * @template T - Type du service attendu (doit étendre IBaseService)
   * @param name - Nom du service à récupérer
   * @returns L'instance du service typée
   * @throws Error si le service n'existe pas dans le conteneur
   *
   * @example
   * const logger = container.get<LoggerService>("LoggerService");
   * logger.info("Message de log");
   */
  public get<T extends IBaseService>(name: string): T {
    const service = this.services.get(name);

    if (!service) {
      throw new Error(`Service "${name}" non trouvé dans le conteneur`);
    }

    return service as T;
  }

  /**
   * Récupère tous les services enregistrés dans le conteneur
   * Utile pour des opérations globales comme l'initialisation ou le nettoyage
   *
   * @returns Tableau contenant toutes les instances de services
   *
   * @example
   * const allServices = container.getAll();
   * console.log(`${allServices.length} services enregistrés`);
   */
  public getAll(): IBaseService[] {
    return Array.from(this.services.values());
  }

  /**
   * Initialise tous les services enregistrés de manière asynchrone
   *
   * Cette méthode appelle la méthode init() de chaque service en parallèle
   * via Promise.all, ce qui optimise le temps de démarrage de l'application
   *
   * L'ordre d'initialisation n'est pas garanti. Si des services ont des
   * dépendances entre eux, ils doivent gérer cela via le contexte partagé.
   *
   * @throws Error si l'initialisation d'un service échoue
   *
   * @example
   * await container.initializeAll();
   * console.log("Tous les services sont prêts");
   */
  public async initializeAll(): Promise<void> {
    const allServices = this.getAll();

    // Initialisation parallèle de tous les services pour optimiser le démarrage
    await Promise.all(allServices.map((service) => service.init()));
  }
}

import { execSync } from "node:child_process";
import { BaseService } from "./base-service.service.js";
import { IShellService } from "@/types/shell-service.interface.js";
import { promisify } from "util";
import { exec } from "child_process";

// On transforme exec en version qui retourne une Promise
const execPromise = promisify(exec);
export class ShellService extends BaseService implements IShellService {
  /**
   * Exécute une commande de manière asynchrone
   * Attention, cela ne bloque pas l'Event Loop.
   */
  async execute(command: string): Promise<string> {
    try {
      console.log(`> Exécution (async) de : ${command}...`);

      // On attend le résultat sans bloquer le reste du serveur
      const { stdout, stderr } = await execPromise(command, {
        encoding: "utf-8",
      });

      if (stderr) {
        console.warn(`Avertissement Shell : ${stderr}`);
      }

      return stdout;
    } catch (error: any) {
      console.error(`Erreur critique : ${error.message}`);
      throw new Error(`Échec de la commande ${command}: ${error.message}`);
    }
  }
  /**
   * Exécute une commande de manière synchrone.
   * Attention, cela bloque l'Event Loop.
   */
  executeSync(command: string): string {
    try {
      console.log(`> Exécution de : ${command}...`);

      // Utilisation de la fonction importée de 'child_process'
      // et non de 'this.executeSync'
      const output = execSync(command, { encoding: "utf-8" });

      return output;
    } catch (error: any) {
      console.error(`Erreur : ${error.message}`);
      return `Erreur lors de l'exécution de ${command}: ${error.message}`;
    }
  }
}

